export function translate(language:Language,key:TranslationKey,values:Record<string,string|number>={}){
  const source=key in localImageCopy[language]?localImageCopy[language][key as LocalImageKey]:dictionaries[language][key];
  return Object.entries(values).reduce((text,[name,value])=>text.replaceAll(`{${name}}`,String(value)),source);
}

export function useI18n(){
  const language=usePreferences(state=>state.language);
  const t:Translator=(key,values)=>translate(language,key,values);
  return {language,locale:locales[language],t};
}
